// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createOwner, createPet, createVisit, updateVisit, getVisit } from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const ownersPostResponse = await createOwner(
        client, "Testbot", "Duration", "1 Test Way", "Testville", "5550001111"
    );

    expect(getResponseValue(ownersPostResponse, "firstName"), 'firstName').toBe("Testbot");
    expect(getResponseValue(ownersPostResponse, "lastName"), 'lastName').toBe("Duration");
    expect(getResponseValue(ownersPostResponse, "city"), 'city').toBe("Testville");
    expect(getResponseValue(ownersPostResponse, "id"), 'owner id').toBeGreaterThan(0);

    const petsPostResponse = await createPet(
        client, getResponseValue(ownersPostResponse, "id"), "Probe", "2020-01-01", 1, "cat"
    );

    expect(getResponseValue(petsPostResponse, "name"), 'pet name').toBe("Probe");
    expect(getResponseValue(petsPostResponse, "birthDate"), 'pet birthDate').toBe("2020-01-01");
    expect(getResponseValue(petsPostResponse, "type.name"), 'pet type').toBe("cat");
    expect(getResponseValue(petsPostResponse, "ownerId"), 'pet ownerId').toBe(getResponseValue(ownersPostResponse, "id"));
    expect(getResponseValue(petsPostResponse, "id"), 'pet id').toBeGreaterThan(0);

    const visitsPostResponse = await createVisit(
        client,
        getResponseValue(ownersPostResponse, "id"),
        getResponseValue(petsPostResponse, "id"),
        "2026-09-02",
        "annual checkup",
        30
    );

    expect(getResponseValue(visitsPostResponse, "date"), 'visit date').toBe("2026-09-02");
    expect(getResponseValue(visitsPostResponse, "description"), 'visit description').toBe("annual checkup");
    expect(getResponseValue(visitsPostResponse, "durationMinutes"), 'duration booked on create').toBe(30);
    expect(getResponseValue(visitsPostResponse, "petId"), 'visit petId').toBe(getResponseValue(petsPostResponse, "id"));
    expect(getResponseValue(visitsPostResponse, "id"), 'visit id').toBeGreaterThan(0);

    await updateVisit(
        client,
        getResponseValue(visitsPostResponse, "id"),
        "2026-09-02",
        "annual checkup",
        90
    );

    const visitsVisitsGetResponse = await getVisit(
        client, getResponseValue(visitsPostResponse, "id")
    );

    expect(getResponseValue(visitsVisitsGetResponse, "id"), 'visit id unchanged').toBe(getResponseValue(visitsPostResponse, "id"));
    expect(getResponseValue(visitsVisitsGetResponse, "date"), 'visit date').toBe("2026-09-02");
    expect(getResponseValue(visitsVisitsGetResponse, "description"), 'visit description').toBe("annual checkup");
    // The PR description states the appointment length "can be changed" from the edit form,
    // which submits this PUT. The re-read must therefore report the updated 90 minutes.
    expect(getResponseValue(visitsVisitsGetResponse, "durationMinutes"), 'duration after update').toBe(90);
    expect(getResponseValue(visitsVisitsGetResponse, "durationMinutes"), 'duration at most the 240 minute maximum').toBeLessThanOrEqual(240);
});
